<script lang="ts">
  import { createBrowserClient } from '@supabase/ssr';
  import { PUBLIC_SUPABASE_URL, PUBLIC_SUPABASE_PUBLISHABLE_KEY } from '$env/static/public';
  import { invalidateAll } from '$app/navigation';
  import { Search, Plus, Pencil, Trash2, X, Users } from 'lucide-svelte';
  export let data;
  const supabase = createBrowserClient(PUBLIC_SUPABASE_URL, PUBLIC_SUPABASE_PUBLISHABLE_KEY);
  let query = '', modal = false, editing: any = null, busy = false, message = '', error = '';
  let form = { full_name:'', student_id:'', email:'', phone:'', active:true };
  $: filtered = data.borrowers.filter((b: any) => [b.full_name,b.student_id,b.email,b.phone].some((v: string | null) => (v ?? '').toLowerCase().includes(query.toLowerCase())));
  function openNew() { editing=null; form={full_name:'',student_id:'',email:'',phone:'',active:true}; error=''; message=''; modal=true; }
  function openEdit(b: any) { editing=b; form={full_name:b.full_name,student_id:b.student_id??'',email:b.email??'',phone:b.phone??'',active:b.active}; error=''; message=''; modal=true; }
  async function save() {
    busy=true; error=''; message='';
    const payload={full_name:form.full_name.trim(),student_id:form.student_id.trim()||null,email:form.email.trim()||null,phone:form.phone.trim()||null,active:form.active};
    const result=editing ? await supabase.from('borrowers').update(payload).eq('id',editing.id) : await supabase.from('borrowers').insert(payload);
    busy=false; if(result.error){error=result.error.message;return;}
    modal=false; message=editing?'Borrower updated.':'Borrower registered.'; await invalidateAll();
  }
  async function remove(b: any) {
    if(!confirm(`Delete borrower "${b.full_name}"? Borrowers with loan history cannot be deleted.`)) return;
    const {error:e}=await supabase.from('borrowers').delete().eq('id',b.id);
    if(e) error=e.message.includes('foreign key')?'This borrower has borrowing history. Deactivate the record instead.':e.message;
    else {message='Borrower deleted.';await invalidateAll();}
  }
</script>

<div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm font-semibold text-indigo-600">PEOPLE</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Borrowers</h1><p class="mt-2 text-sm text-slate-500">Register and maintain borrower records.</p></div><button on:click={openNew} class="inline-flex items-center justify-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700"><Plus size={17}/> Add borrower</button></div>
{#if message}<div class="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{message}</div>{/if}
{#if error || data.error}<div class="mb-4 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error || data.error}</div>{/if}
<div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
  <div class="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-bold text-slate-900">Borrower directory</h2><p class="mt-1 text-xs text-slate-500">{filtered.length} record(s)</p></div><div class="relative w-full sm:max-w-xs"><Search size={17} class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input bind:value={query} placeholder="Search name, ID, email..." class="w-full rounded-xl border border-slate-200 py-2.5 pl-9 pr-3 text-sm outline-none focus:border-indigo-500"/></div></div>
  {#if filtered.length}<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Borrower</th><th class="px-5 py-3">Student/Library ID</th><th class="px-5 py-3">Contact</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100">{#each filtered as b}<tr class="hover:bg-slate-50/70"><td class="px-5 py-4"><div class="flex items-center gap-3"><div class="grid h-10 w-10 place-items-center rounded-xl bg-sky-50 text-sky-700"><Users size={18}/></div><div class="font-semibold text-slate-800">{b.full_name}</div></div></td><td class="px-5 py-4 text-slate-500">{b.student_id || '—'}</td><td class="px-5 py-4"><div class="text-slate-700">{b.email || '—'}</div><div class="mt-1 text-xs text-slate-500">{b.phone || ''}</div></td><td class="px-5 py-4">{#if b.active}<span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">Active</span>{:else}<span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-500">Inactive</span>{/if}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><button title="Edit" on:click={() => openEdit(b)} class="rounded-lg p-2 text-slate-500 hover:bg-indigo-50 hover:text-indigo-700"><Pencil size={16}/></button><button title={b.active?'Deactivate':'Reactivate'} on:click={async()=>{const {error:e}=await supabase.from('borrowers').update({active:!b.active}).eq('id',b.id);if(e)error=e.message;else{message=b.active?'Borrower deactivated.':'Borrower reactivated.';await invalidateAll();}}} class="rounded-lg p-2 text-slate-500 hover:bg-amber-50 hover:text-amber-700"><span class="text-xs font-bold">{b.active?'Off':'On'}</span></button><button title="Delete" on:click={() => remove(b)} class="rounded-lg p-2 text-slate-500 hover:bg-rose-50 hover:text-rose-700"><Trash2 size={16}/></button></div></td></tr>{/each}</tbody></table></div>{:else}<div class="p-12 text-center"><Users class="mx-auto h-9 w-9 text-slate-300"/><h3 class="mt-3 font-semibold text-slate-800">No borrowers found</h3><p class="mt-1 text-sm text-slate-500">Try another search or register a borrower.</p></div>{/if}
</div>
{#if modal}<div class="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4" role="presentation" on:click={(e)=>{if(e.target===e.currentTarget)modal=false;}}><div role="dialog" aria-modal="true" class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl"><div class="mb-5 flex items-center justify-between"><div><h2 class="text-xl font-bold">{editing?'Edit borrower':'Register borrower'}</h2><p class="mt-1 text-sm text-slate-500">Enter the borrower's details.</p></div><button on:click={()=>modal=false} class="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={19}/></button></div>{#if error}<div class="mb-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{error}</div>{/if}<form on:submit|preventDefault={save} class="space-y-4"><div><label for="borrower-name" class="mb-1.5 block text-sm font-semibold">Full name *</label><input id="borrower-name" bind:value={form.full_name} required maxlength="160" class="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-indigo-500"/></div><div><label for="borrower-student-id" class="mb-1.5 block text-sm font-semibold">Student/Library ID</label><input id="borrower-student-id" bind:value={form.student_id} maxlength="80" class="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-indigo-500"/></div><div><label for="borrower-email" class="mb-1.5 block text-sm font-semibold">Email</label><input id="borrower-email" type="email" bind:value={form.email} class="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-indigo-500"/></div><div><label for="borrower-phone" class="mb-1.5 block text-sm font-semibold">Phone</label><input id="borrower-phone" bind:value={form.phone} maxlength="40" class="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-indigo-500"/></div><label class="flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={form.active} class="accent-indigo-600"/> Active borrower</label><div class="flex justify-end gap-3 border-t border-slate-100 pt-4"><button type="button" on:click={()=>modal=false} class="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold">Cancel</button><button disabled={busy} class="rounded-xl bg-indigo-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{busy?'Saving…':editing?'Save changes':'Register borrower'}</button></div></form></div></div>{/if}
